// requirement: REQ-1.1
import { test, expect } from "@playwright/test";
import { field, nav, visible, heading, openHome, installClock } from "./helpers";

test.beforeEach(async ({ page }) => { await installClock(page); });

test('REQ-1.1: Show signed-out entry', async ({ page }, testInfo) => {
  await openHome(page);
  await expect(page.getByRole('heading', { name: 'Ctrip Travel', exact: true })).toHaveCount(1);
  await heading(page, 'Ctrip Travel');
  await expect(nav(page).getByRole('link', { name: 'Log in', exact: true })).toHaveCount(1);
  await expect(nav(page).getByRole('link', { name: 'Register', exact: true })).toHaveCount(1);
  await visible(nav(page).getByRole('link', { name: 'Log in', exact: true }));
  await visible(nav(page).getByRole('link', { name: 'Register', exact: true }));
  await visible(page.getByRole('searchbox'));
  await visible(field(page, 'Origin'));
  await visible(field(page, 'Destination'));
});

// requirement: REQ-1.10
import { test, expect } from "@playwright/test";
import { field, button, action, heading, alertText, openHome, installClock, registrationPhone, registerToPassword } from "./helpers";

test.beforeEach(async ({ page }) => { await installClock(page); });

test('REQ-1.10: Reject a letters-only registration password', async ({ page }, testInfo) => {
  await openHome(page);
  await registerToPassword(page, registrationPhone(testInfo));
  await field(page, 'Password').fill('abcdefgh');
  await field(page, 'Confirm password').fill('abcdefgh');
  await button(page, 'Complete registration').click();
  await alertText(page, 'Password must contain letters and numbers and be at least 8 characters');
  await heading(page, 'Set password');
  await expect(action(page, 'My account')).toHaveCount(0);
});

